import{_ as t,o as a,c as r,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const p=JSON.parse('{"title":"拉尔夫·谢伊","description":"","frontmatter":{"title":"拉尔夫·谢伊","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/拉尔夫·谢伊.md","filePath":"04_people/拉尔夫·谢伊.md"}'),o={name:"04_people/拉尔夫·谢伊.md"};function i(s,e,n,_,h,c){return a(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="拉尔夫·谢伊" tabindex="-1">拉尔夫·谢伊 <a class="header-anchor" href="#拉尔夫·谢伊" aria-label="Permalink to &quot;拉尔夫·谢伊&quot;">​</a></h1><ul><li><strong>角色职位</strong>：世界图书（World Book）、Kirby、Scott Fetzer 管理者</li><li><strong>与巴菲特关系</strong>：伯克希尔·哈撒韦旗下多家子公司运营负责人</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>拉尔夫·谢伊是伯克希尔·哈撒韦旗下多家重要子公司的核心管理者。在他的管理下，世界图书公司保持着稳健的运营，成为伯克希尔大家庭中可靠的事业板块。谢伊负责运营的Scott Fetzer子公司群涵盖多个细分业务领域，他以精简高效的管理风格著称。</p><p>谢伊在伯克希尔的角色体现了巴菲特一贯的经营理念——找到优秀的管理人才，充分授权，让他们自主运营。作为一名低调但能力出众的管理者，谢伊在巴菲特收购后的整合过程中发挥了关键作用，确保各子公司在伯克希尔的伞下继续健康发展。</p><p>巴菲特对谢伊的管理能力颇为信任，将多家业务性质各异的公司交由其统一协调管理，这种&quot;一个优秀管理者、多项分散业务&quot;的模式，正是伯克希尔商业模式的一个缩影。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1986年</strong>：随伯克希尔收购Scott Fetzer，成为旗下多家子公司管理者</li><li><strong>1990年代</strong>：持续管理世界图书、Kirby等子公司，保持稳定盈利</li><li><strong>2000年代</strong>：继续担任Scott Fetzer业务群的管理职责</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search?q=拉尔夫·谢伊在1994年股东信中的原话">1994年：完整翻译|/01_letters/1994年/翻译</a></li><li><a href="/search?q=拉尔夫·谢伊在1986年股东信中的原话">1986年：完整翻译|/01_letters/1986年/翻译</a></li><li><a href="/search?q=拉尔夫·谢伊在1985年股东信中的原话">1985年：完整翻译|/01_letters/1985年/翻译</a></li><li><a href="/search?q=拉尔夫·谢伊在1990年股东信中的原话">1990年：完整翻译|/01_letters/1990年/翻译</a></li><li><a href="/search?q=拉尔夫·谢伊在1999年股东信中的原话">1999年：完整翻译|/01_letters/1999年/翻译</a></li></ul>',11)])])}const u=t(o,[["render",i]]);export{p as __pageData,u as default};
